INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (501, 'tt0089218', 9340, 'The Goonies', 1985, '/eBU7gCjTCj9n2LTxvCSIXXOvHkD.jpg', '{12,35,10751}', 'Young teen Mikey Walsh and his friends set off on a quest to find Pirate One-Eyed Willie''s treasure in hopes of saving their homes from demolition. However, on their quest to find the treasure, they run into a family of recently escaped criminals, determined to capture the kids and reach the treasure first.', '[{"name": "Sean Astin", "character": "Mikey"}, {"name": "Josh Brolin", "character": "Brand"}, {"name": "Jeff Cohen", "character": "Chunk"}, {"name": "Corey Feldman", "character": "Mouth"}, {"name": "Kerri Green", "character": "Andy"}]', 'Richard Donner', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (502, 'tt0092099', 744, 'Top Gun', 1986, '/xUuHj3CgmZQ9P2cMaqQs4J0d4Zc.jpg', '{28,18,10749}', 'For Lieutenant Pete ''Maverick'' Mitchell and his friend and co-pilot Nick ''Goose'' Bradshaw, being accepted into an elite training school for fighter pilots is a dream come true. But a tragedy, as well as personal demons, will threaten Pete''s dreams of becoming an ace pilot.', '[{"name": "Tom Cruise", "character": "Maverick"}, {"name": "Kelly McGillis", "character": "Charlie"}, {"name": "Val Kilmer", "character": "Ice"}, {"name": "Anthony Edwards", "character": "Goose"}, {"name": "Tom Skerritt", "character": "Viper"}]', 'Tony Scott', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (505, 'tt0096895', 268, 'Batman', 1989, '/cij4dd21v2Rk2YtUQbV5kW69WB2.jpg', '{14,28,80}', 'Having witnessed his parents'' brutal murder as a child, millionaire philanthropist Bruce Wayne fights crime in Gotham City disguised as Batman, a costumed hero who strikes fear into the hearts of villains. But when a deformed madman known as ''The Joker'' seizes control of Gotham''s criminal underworld, Batman must face his most ruthless nemesis ever while protecting both his identity and his love interest, reporter Vicki Vale.', '[{"name": "Michael Keaton", "character": "Batman / Bruce Wayne"}, {"name": "Jack Nicholson", "character": "Joker / Jack Napier"}, {"name": "Kim Basinger", "character": "Vicki Vale"}, {"name": "Robert Wuhl", "character": "Alexander Knox"}, {"name": "Pat Hingle", "character": "Commissioner Gordon"}]', 'Tim Burton', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (508, 'tt0116629', 602, 'Independence Day', 1996, '/p0BPQGSPoSa8Ml0DAf2mB2kCU0R.jpg', '{28,12,878}', 'Strange phenomena surface around the globe. The skies ignite. Terror races through the world''s major cities. As these extraordinary events unfold, it becomes increasingly clear that a force of incredible magnitude has arrived. Its mission: total annihilation over the Fourth of July weekend. The last hope to stop the destruction is an unlikely group of people united by fate and unimaginable circumstances.', '[{"name": "Will Smith", "character": "Capt. Steven Hiller"}, {"name": "Bill Pullman", "character": "President Thomas J. Whitmore"}, {"name": "Jeff Goldblum", "character": "David Levinson"}, {"name": "Mary McDonnell", "character": "Marilyn Whitmore"}, {"name": "Judd Hirsch", "character": "Julius Levinson"}]', 'Roland Emmerich', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (511, 'tt0119654', 607, 'Men in Black', 1997, '/uLOmOF5IzWoyrgIF5MfUnh5pa1X.jpg', '{28,12,35,878}', 'After a police chase with an otherworldly being, a New York City cop is recruited as an agent in a top-secret organization established to monitor and police alien activity on Earth: the Men in Black. Agent K and new recruit Agent J find themselves in the middle of a deadly plot by an intergalactic terrorist who has arrived on Earth to assassinate two ambassadors from opposing galaxies.', '[{"name": "Tommy Lee Jones", "character": "Kay"}, {"name": "Will Smith", "character": "Jay"}, {"name": "Linda Fiorentino", "character": "Laurel"}, {"name": "Vincent D''Onofrio", "character": "Edgar"}, {"name": "Rip Torn", "character": "Zed"}]', 'Barry Sonnenfeld', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (513, 'tt0125439', 509, 'Notting Hill', 1999, '/hHRIf2XHeQMbyRb3HUx19SF5Ujw.jpg', '{10749,35}', 'London bookstore owner William Thacker''s quiet life turns upside down when a chance encounter with famous actress Anna Scott sparks an unlikely romance challenged by their vastly different worlds.', '[{"name": "Julia Roberts", "character": "Anna Scott"}, {"name": "Hugh Grant", "character": "William Thacker"}, {"name": "Gina McKee", "character": "Bella"}, {"name": "Tim McInnerny", "character": "Max"}, {"name": "Rhys Ifans", "character": "Spike"}]', 'Roger Michell', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (514, 'tt0120915', 1893, 'Star Wars: Episode I - The Phantom Menace', 1999, '/xQzMnuiv81d0gfUIVstuleNutjA.jpg', '{12,28,878}', 'Anakin Skywalker, a young slave strong with the Force, is discovered on Tatooine. Meanwhile, the evil Sith have returned, enacting their plot for revenge against the Jedi.', '[{"name": "Liam Neeson", "character": "Qui-Gon Jinn"}, {"name": "Ewan McGregor", "character": "Obi-Wan Kenobi"}, {"name": "Natalie Portman", "character": "Padmé Amidala"}, {"name": "Jake Lloyd", "character": "Anakin Skywalker"}, {"name": "Ian McDiarmid", "character": "Senator Palpatine"}]', 'George Lucas', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (515, 'tt0241527', 671, 'Harry Potter and the Philosopher''s Stone', 2001, '/wuMc08IPKEatf9rnMNXvIDxqP4W.jpg', '{12,14}', 'Harry Potter has lived under the stairs at his aunt and uncle''s house his whole life. But on his 11th birthday, he learns he''s a powerful wizard—with a place waiting for him at the Hogwarts School of Witchcraft and Wizardry. As he learns to harness his newfound powers with the help of the school''s kindly headmaster, Harry uncovers the truth about his parents'' deaths—and about the villain who''s to blame.', '[{"name": "Daniel Radcliffe", "character": "Harry Potter"}, {"name": "Rupert Grint", "character": "Ron Weasley"}, {"name": "Emma Watson", "character": "Hermione Granger"}, {"name": "Richard Harris", "character": "Albus Dumbledore"}, {"name": "Tom Felton", "character": "Draco Malfoy"}]', 'Chris Columbus', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (516, 'tt0240772', 161, 'Ocean''s Eleven', 2001, '/hQQCdZrsHtZyR6NbKH2YyCqd2fR.jpg', '{53,80}', 'Less than 24 hours into his parole, charismatic thief Danny Ocean is already rolling out his next plan: In one night, Danny''s hand-picked crew of specialists will attempt to steal more than $150 million from three Las Vegas casinos. But to score the cash, Danny risks his chances of reconciling with ex-wife, Tess.', '[{"name": "George Clooney", "character": "Danny Ocean"}, {"name": "Brad Pitt", "character": "Rusty Ryan"}, {"name": "Andy Garcia", "character": "Terry Benedict"}, {"name": "Matt Damon", "character": "Linus Caldwell"}, {"name": "Julia Roberts", "character": "Tess Ocean"}]', 'Steven Soderbergh', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (517, 'tt0145487', 557, 'Spider-Man', 2002, '/kjdJntyBeEvqm9w97QGBdxPptzj.jpg', '{28,878}', 'After being bitten by a genetically altered spider at Oscorp, nerdy but endearing high school student Peter Parker is endowed with amazing powers to become the superhero known as Spider-Man.', '[{"name": "Tobey Maguire", "character": "Spider-Man / Peter Parker"}, {"name": "Willem Dafoe", "character": "Green Goblin / Norman Osborn"}, {"name": "Kirsten Dunst", "character": "Mary Jane Watson"}, {"name": "James Franco", "character": "Harry Osborn"}, {"name": "Cliff Robertson", "character": "Ben Parker"}]', 'Sam Raimi', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (518, 'tt0299658', 1574, 'Chicago', 2002, '/3ED8cWCXY9zkx77Sd0N5qMbsdDP.jpg', '{35,80,18}', 'Murderesses Velma Kelly and Roxie Hart find themselves on death row together and fight for the fame that will keep them from the gallows in 1920s Chicago.', '[{"name": "Renée Zellweger", "character": "Roxie Hart"}, {"name": "Catherine Zeta-Jones", "character": "Velma Kelly"}, {"name": "Richard Gere", "character": "Billy Flynn"}, {"name": "Queen Latifah", "character": "Matron Mama Morton"}, {"name": "Ekaterina Chtchelkanova", "character": "Katalin Helinski \"Hunyak\""}]', 'Rob Marshall', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (519, 'tt0298148', 809, 'Shrek 2', 2004, '/2yYP0PQjG8zVqturh1BAqu2Tixl.jpg', '{16,35,10751,14,10749}', 'Happily ever after never seemed so far far away when a trip to meet the in-laws turns into a hilariously twisted adventure for Shrek and Fiona. With the help of ever-faithful Donkey, Shrek takes on the potion-brewing Fairy Godmother, pompous Prince Charming, and infamous ogre-killer Puss In Boots.', '[{"name": "Mike Myers", "character": "Shrek (voice)"}, {"name": "Eddie Murphy", "character": "Donkey (voice)"}, {"name": "Cameron Diaz", "character": "Princess Fiona (voice)"}, {"name": "Julie Andrews", "character": "Queen Lillian (voice)"}, {"name": "Antonio Banderas", "character": "Puss in Boots (voice)"}]', 'Conrad Vernon', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (520, 'tt0416449', 1271, '300', 2007, '/h7Lcio0c9ohxPhSZg42eTlKIVVY.jpg', '{28,12,10752}', 'A story very loosely based the 480 B.C. Battle of Thermopylae, where the King of Sparta led his army against the advancing Persians.', '[{"name": "Gerard Butler", "character": "King Leonidas"}, {"name": "Lena Headey", "character": "Gorgo"}, {"name": "Dominic West", "character": "Theron"}, {"name": "David Wenham", "character": "Dilios/Narrator"}, {"name": "Vincent Regan", "character": "Captain"}]', 'Zack Snyder', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (521, 'tt0467406', 7326, 'Juno', 2007, '/jNIn2tVhpvFD6P9IojldI3mNYcn.jpg', '{35,18,10749}', 'Faced with an unplanned pregnancy, sixteen year old high-schooler, Juno MacGuff, makes an unusual decision regarding her unborn child.', '[{"name": "Elliot Page", "character": "Juno MacGuff"}, {"name": "Michael Cera", "character": "Paulie Bleeker"}, {"name": "Jennifer Garner", "character": "Vanessa Loring"}, {"name": "Jason Bateman", "character": "Mark Loring"}, {"name": "J.K. Simmons", "character": "Mac MacGuff"}]', 'Jason Reitman', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (522, 'tt1022603', 19913, '(500) Days of Summer', 2009, '/qXAuQ9hF30sQRsXf40OfRVl0MJZ.jpg', '{35,18,10749}', 'Tom, greeting-card writer and hopeless romantic, is caught completely off-guard when his girlfriend, Summer, suddenly dumps him. He reflects on their 500 days together to try to figure out where their love affair went sour, and in doing so, Tom rediscovers his true passions in life.', '[{"name": "Joseph Gordon-Levitt", "character": "Tom"}, {"name": "Zooey Deschanel", "character": "Summer"}, {"name": "Geoffrey Arend", "character": "McKenzie"}, {"name": "Chloë Grace Moretz", "character": "Rachel"}, {"name": "Matthew Gray Gubler", "character": "Paul"}]', 'Marc Webb', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (523, 'tt1605783', 59436, 'Midnight in Paris', 2011, '/4wBG5kbfagTQclETblPRRGihk0I.jpg', '{14,35,10749}', 'While on a trip to Paris with his fiancée''s family, a nostalgic screenwriter finds himself mysteriously going back to the 1920s every day at midnight.', '[{"name": "Owen Wilson", "character": "Gil"}, {"name": "Rachel McAdams", "character": "Inez"}, {"name": "Kathy Bates", "character": "Gertrude Stein"}, {"name": "Kurt Fuller", "character": "John"}, {"name": "Adrien Brody", "character": "Salvador Dalí"}]', 'Woody Allen', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (524, 'tt1045658', 82693, 'Silver Linings Playbook', 2012, '/fhHB1uvfFKKFbj6bTKE8xdtsjKi.jpg', '{18,35,10749}', 'After losing his job and wife, and spending time in an institution, a former teacher winds up living with his parents. He wants to rebuild his life and reconcile with his wife, but his father would be happy if he shared his obsession with the Philadelphia Eagles. Things get complicated when he meets Tiffany Maxwell who offers to help him reconnect with his wife if he will do something very important for her in exchange.', '[{"name": "Bradley Cooper", "character": "Pat Solatano Jr."}, {"name": "Jennifer Lawrence", "character": "Tiffany Maxwell"}, {"name": "Robert De Niro", "character": "Pat Solatano Sr."}, {"name": "Jacki Weaver", "character": "Dolores Solatano"}, {"name": "Anupam Kher", "character": "Dr. Cliff Patel"}]', 'David O. Russell', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (525, 'tt1024648', 68734, 'Argo', 2012, '/m5gPWFZFIp4UJFABgWyLkbXv8GX.jpg', '{18,53}', 'As the Iranian revolution reaches a boiling point, a CIA ''exfiltration'' specialist concocts a risky plan to free six Americans who have found shelter at the home of the Canadian ambassador.', '[{"name": "Ben Affleck", "character": "Tony Mendez"}, {"name": "Bryan Cranston", "character": "Jack O''Donnell"}, {"name": "Alan Arkin", "character": "Lester Siegel"}, {"name": "John Goodman", "character": "John Chambers"}, {"name": "Victor Garber", "character": "Ken Taylor"}]', 'Ben Affleck', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (526, 'tt1454468', 49047, 'Gravity', 2013, '/kZ2nZw8D681aphje8NJi8EfbL1U.jpg', '{878,53,18}', 'Dr Ryan Stone, an engineer on her first space mission, and Matt Kowalski, an astronaut on his final expedition, have to survive in space after they are hit by debris while spacewalking.', '[{"name": "Sandra Bullock", "character": "Ryan Stone"}, {"name": "George Clooney", "character": "Matt Kowalski"}, {"name": "Ed Harris", "character": "Mission Control (voice)"}, {"name": "Orto Ignatiussen", "character": "Aningaaq (voice)"}, {"name": "Phaldut Sharma", "character": "Shariff (voice)"}]', 'Alfonso Cuarón', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (528, 'tt1517451', 332562, 'A Star Is Born', 2018, '/wrFpXMNBRj2PBiN4Z5kix51XaIZ.jpg', '{10402,18,10749}', 'Seasoned musician Jackson Maine discovers- and falls in love with- struggling artist Ally. She has just about given up on her dream to make it big as a singer- until Jack coaxes her into the spotlight. But even as Ally''s career takes off, the personal side of their relationship is breaking down, as Jack fights an ongoing battle with his own internal demons.', '[{"name": "Lady Gaga", "character": "Ally Campana"}, {"name": "Bradley Cooper", "character": "Jackson Maine"}, {"name": "Sam Elliott", "character": "Bobby Maine"}, {"name": "Andrew Dice Clay", "character": "Lorenzo Campana"}, {"name": "Rafi Gavron", "character": "Rez Gavron"}]', 'Bradley Cooper', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (529, 'tt7131622', 466272, 'Once Upon a Time... in Hollywood', 2019, '/8j58iEBw9pOXFD2L0nt0ZXeHviB.jpg', '{35,18,53}', 'Los Angeles, 1969. TV star Rick Dalton, a struggling actor specializing in westerns, and stuntman Cliff Booth, his best friend, try to survive in a constantly changing movie industry. Dalton is the neighbor of the young and promising actress and model Sharon Tate, who has just married the prestigious Polish director Roman Polanski…', '[{"name": "Leonardo DiCaprio", "character": "Rick Dalton"}, {"name": "Brad Pitt", "character": "Cliff Booth"}, {"name": "Margot Robbie", "character": "Sharon Tate"}, {"name": "Emile Hirsch", "character": "Jay Sebring"}, {"name": "Margaret Qualley", "character": "''Pussycat''"}]', 'Quentin Tarantino', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (531, 'tt6723592', 577922, 'Tenet', 2020, '/aCIFMriQh8rvhxpN1IWGgvH0Tlg.jpg', '{28,53,878}', 'Armed with only one word - Tenet - and fighting for the survival of the entire world, the Protagonist journeys through a twilight world of international espionage on a mission that will unfold in something beyond real time.', '[{"name": "John David Washington", "character": "Protagonist"}, {"name": "Robert Pattinson", "character": "Neil"}, {"name": "Elizabeth Debicki", "character": "Kat"}, {"name": "Kenneth Branagh", "character": "Sator"}, {"name": "Dimple Kapadia", "character": "Priya"}]', 'Christopher Nolan', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (532, 'tt6710474', 545611, 'Everything Everywhere All at Once', 2022, '/u68AjlvlutfEIcpmbYpKcdi09ut.jpg', '{28,12,878}', 'An aging Chinese immigrant is swept up in an insane adventure, where she alone can save what''s important to her by connecting with the lives she could have led in other universes.', '[{"name": "Michelle Yeoh", "character": "Evelyn Wang"}, {"name": "Stephanie Hsu", "character": "Joy Wang / Jobu Tupaki"}, {"name": "Ke Huy Quan", "character": "Waymond Wang"}, {"name": "James Hong", "character": "Gong Gong"}, {"name": "Jamie Lee Curtis", "character": "Deirdre Beaubeirdre"}]', 'Daniel Scheinert', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (534, 'tt1517268', 346698, 'Barbie', 2023, '/iuFNMS8U5cb6xfzi51Dbkovj7vM.jpg', '{35,12,14}', 'Barbie and Ken are having the time of their lives in the colorful and seemingly perfect world of Barbie Land. However, when they get a chance to go to the real world, they soon discover the joys and perils of living among humans.', '[{"name": "Margot Robbie", "character": "Barbie"}, {"name": "Ryan Gosling", "character": "Ken"}, {"name": "America Ferrera", "character": "Gloria"}, {"name": "Ariana Greenblatt", "character": "Sasha"}, {"name": "Issa Rae", "character": "Barbie"}]', 'Greta Gerwig', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (538, 'tt0087800', 377, 'A Nightmare on Elm Street', 1984, '/b9rMHAAKISRmIonaQd9Cccx0S4X.jpg', '{27}', 'Teenagers in a small town are dropping like flies, apparently in the grip of mass hysteria causing their suicides. A cop''s daughter, Nancy Thompson, traces the cause to child molester Fred Krueger, who was burned alive by angry parents many years before. Krueger has now come back in the dreams of his killers'' children, claiming their lives as his revenge. Nancy and her boyfriend, Glen, must devise a plan to lure the monster out of the realm of nightmares and into the real world...', '[{"name": "Heather Langenkamp", "character": "Nancy Thompson"}, {"name": "Johnny Depp", "character": "Glen Lantz"}, {"name": "Robert Englund", "character": "Fred Krueger"}, {"name": "Amanda Wyss", "character": "Tina Gray"}, {"name": "Jsu Garcia", "character": "Rod Lane"}]', 'Wes Craven', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (544, 'tt0092890', 88, 'Dirty Dancing', 1987, '/9Jw6jys7q9gjzVX5zm1z0gC8gY9.jpg', '{18,10402,10749}', 'Expecting the usual tedium that accompanies a summer in the Catskills with her family, 17-year-old Frances ''Baby'' Houseman is surprised to find herself stepping into the shoes of a professional hoofer—and unexpectedly falling in love.', '[{"name": "Jennifer Grey", "character": "Frances \"Baby\" Houseman"}, {"name": "Patrick Swayze", "character": "Johnny Castle"}, {"name": "Cynthia Rhodes", "character": "Penny Johnson"}, {"name": "Neal Jones", "character": "Billy Kostecki"}, {"name": "Jerry Orbach", "character": "Dr. Jake Houseman"}]', 'Emile Ardolino', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (545, 'tt0097757', 10144, 'The Little Mermaid', 1989, '/plcZXvI310FkbwIptvd6rqk63LP.jpg', '{16,10751,14}', 'This colorful adventure tells the story of an impetuous mermaid princess named Ariel who falls in love with the very human Prince Eric and puts everything on the line for the chance to be with him. Memorable songs and characters -- including the villainous sea witch Ursula.', '[{"name": "Jodi Benson", "character": "Ariel (voice)"}, {"name": "Samuel E. Wright", "character": "Sebastian (voice)"}, {"name": "Pat Carroll", "character": "Ursula (voice)"}, {"name": "Christopher Daniel Barnes", "character": "Eric (voice)"}, {"name": "Kenneth Mars", "character": "Triton (voice)"}]', 'John Musker', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (547, 'tt0100405', 114, 'Pretty Woman', 1990, '/hVHUfT801LQATGd26VPzhorIYza.jpg', '{10749,35}', 'Vivian is a carefree, streetwise diamond in the rough when she meets sophisticated billionaire Edward in a chance encounter that turns into a week-long business arrangement. But Vivian''s energetic spirit challenges Edward''s no-nonsense approach to life, and soon they are teaching each other – and falling in love!', '[{"name": "Richard Gere", "character": "Edward Lewis"}, {"name": "Julia Roberts", "character": "Vivian Ward"}, {"name": "Ralph Bellamy", "character": "James Morse"}, {"name": "Jason Alexander", "character": "Philip Stuckey"}, {"name": "Laura San Giacomo", "character": "Kit De Luca"}]', 'Garry Marshall', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (549, 'tt0107614', 788, 'Mrs. Doubtfire', 1993, '/shHrSmXS5140o6sQzgzXxn3KqSm.jpg', '{35,18,10751}', 'Loving but irresponsible dad Daniel Hillard, estranged from his exasperated spouse, is crushed by a court order allowing only weekly visits with his kids. When Daniel learns his ex needs a housekeeper, he gets the job -- disguised as a British nanny. Soon he becomes not only his children''s best pal but the kind of parent he should have been from the start.', '[{"name": "Robin Williams", "character": "Daniel Hillard / Mrs. Doubtfire"}, {"name": "Sally Field", "character": "Miranda Hillard"}, {"name": "Lisa Jakub", "character": "Lydia Hillard"}, {"name": "Matthew Lawrence", "character": "Chris Hillard"}, {"name": "Mara Wilson", "character": "Natalie Hillard"}]', 'Chris Columbus', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (556, 'tt0117060', 954, 'Mission: Impossible', 1996, '/l5uxY5m5OInWpcExIpKG6AR3rgL.jpg', '{12,28,53}', 'When Ethan Hunt, the leader of a crack espionage team whose perilous operation has gone awry with no explanation, discovers that a mole has penetrated the CIA, he''s surprised to learn that he''s the prime suspect. To clear his name, Hunt now must ferret out the real double agent and, in the process, even the score.', '[{"name": "Tom Cruise", "character": "Ethan Hunt"}, {"name": "Jon Voight", "character": "Jim Phelps"}, {"name": "Emmanuelle Béart", "character": "Claire"}, {"name": "Henry Czerny", "character": "Kittridge"}, {"name": "Jean Reno", "character": "Krieger"}]', 'Brian De Palma', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (564, 'tt0163651', 2105, 'American Pie', 1999, '/5P68by2Thn8wHAziyWGEw2O7hco.jpg', '{35,10749}', 'At a high-school party, four friends find that losing their collective virginity isn''t as easy as they had thought. But they still believe that they need to do so before college. To motivate themselves, they enter a pact to all "score" by their senior prom.', '[{"name": "Jason Biggs", "character": "Jim Levenstein"}, {"name": "Chris Klein", "character": "Chris ''Oz'' Ostreicher"}, {"name": "Thomas Ian Nicholas", "character": "Kevin Meyers"}, {"name": "Alyson Hannigan", "character": "Michelle Flaherty"}, {"name": "Shannon Elizabeth", "character": "Nadia"}]', 'Paul Weitz', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (565, 'tt0232500', 9799, 'The Fast and the Furious', 2001, '/gqY0ITBgT7A82poL9jv851qdnIb.jpg', '{28,80,53}', 'Dominic Toretto is a Los Angeles street racer suspected of masterminding a series of big-rig hijackings. When undercover cop Brian O''Conner infiltrates Toretto''s iconoclastic crew, he falls for Toretto''s sister and must choose a side: the gang or the LAPD.', '[{"name": "Paul Walker", "character": "Brian O''Conner"}, {"name": "Vin Diesel", "character": "Dominic Toretto"}, {"name": "Michelle Rodriguez", "character": "Letty Ortiz"}, {"name": "Jordana Brewster", "character": "Mia Toretto"}, {"name": "Rick Yune", "character": "Johnny Tran"}]', 'Rob Cohen', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (566, 'tt0250494', 8835, 'Legally Blonde', 2001, '/9ohlMrJHQqKhfUKh7Zr3JQqHNLZ.jpg', '{35}', 'Fashionable sorority queen Elle Woods has it all, but, she wants nothing more than to be Mrs. Warner Huntington III. But he dumps her before heading to Harvard Law School. Elle rallies all of her resources and gets into Harvard, determined to win him back. While there, she figures out that there is more to herself than just good looks.', '[{"name": "Reese Witherspoon", "character": "Elle Woods"}, {"name": "Luke Wilson", "character": "Emmetten Richmond"}, {"name": "Selma Blair", "character": "Vivian Kensington"}, {"name": "Matthew Davis", "character": "Warner Huntington III"}, {"name": "Victor Garber", "character": "Professor Callahan"}]', 'Robert Luketic', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (568, 'tt0120903', 36657, 'X-Men', 2000, '/bRDAc4GogyS9ci3ow7UnInOcriN.jpg', '{12,28,878}', 'Two mutants, Rogue and Wolverine, come to a private academy for their kind whose resident superhero team, the X-Men, must oppose a terrorist organization with similar powers.', '[{"name": "Hugh Jackman", "character": "Logan / Wolverine"}, {"name": "Patrick Stewart", "character": "Xavier"}, {"name": "Ian McKellen", "character": "Magneto"}, {"name": "Famke Janssen", "character": "Jean Grey"}, {"name": "James Marsden", "character": "Cyclops"}]', 'Bryan Singer', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (569, 'tt0290334', 36658, 'X2', 2003, '/bst4alFUXCxISwdRUKSMhhkrX1M.jpg', '{12,28,878}', 'Professor Charles Xavier and his team of genetically gifted superheroes face a rising tide of anti-mutant sentiment led by Col. William Stryker. Storm, Wolverine and Jean Grey must join Magneto and Mystique to unhinge Stryker''s scheme to exterminate all mutants.', '[{"name": "Hugh Jackman", "character": "Logan / Wolverine"}, {"name": "Patrick Stewart", "character": "Professor Charles Xavier"}, {"name": "Ian McKellen", "character": "Eric Lehnsherr / Magneto"}, {"name": "James Marsden", "character": "Scott Summers / Cyclops"}, {"name": "Brian Cox", "character": "William Stryker"}]', 'Bryan Singer', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (570, 'tt0298130', 565, 'The Ring', 2002, '/AeRpUynJKDpJveklBJipOYrVxCS.jpg', '{27,9648}', 'Journalist Rachel Keller investigates a strange videotape that may be behind the untimely deaths of four teenagers. There is an urban legend about this tape: the viewer will die seven days after watching it. Rachel tracks down the video... and watches it. Now she has just seven days to unravel the mystery of the Ring in order to save herself and her son.', '[{"name": "Naomi Watts", "character": "Rachel Keller"}, {"name": "Martin Henderson", "character": "Noah Clay"}, {"name": "David Dorfman", "character": "Aidan Keller"}, {"name": "Brian Cox", "character": "Richard Morgan"}, {"name": "Jane Alexander", "character": "Dr. Grasnik"}]', 'Gore Verbinski', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (571, 'tt0268380', 425, 'Ice Age', 2002, '/gLhHHZUzeseRXShoDyC4VqLgsNv.jpg', '{16,35,10751,12}', 'Manny the mammoth, Sid the loquacious sloth, and Diego the sabre-toothed tiger go on a comical quest to return a human baby back to his father, across a world on the brink of an ice age.', '[{"name": "Ray Romano", "character": "Manfred ''Manny'' (voice)"}, {"name": "John Leguizamo", "character": "Sid (voice)"}, {"name": "Denis Leary", "character": "Diego (voice)"}, {"name": "Goran Višnjić", "character": "Soto (voice)"}, {"name": "Jack Black", "character": "Zeke (voice)"}]', 'Chris Wedge', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (573, 'tt0377092', 10625, 'Mean Girls', 2004, '/2ZkuQXvVhh45uSvkBej4S7Ix1NJ.jpg', '{18,35}', 'Cady Heron is a hit with The Plastics, the A-list girl clique at her new school, until she makes the mistake of falling for Aaron Samuels, the ex-boyfriend of alpha Plastic Regina George.', '[{"name": "Lindsay Lohan", "character": "Cady Heron"}, {"name": "Rachel McAdams", "character": "Regina George"}, {"name": "Lizzy Caplan", "character": "Janis Ian"}, {"name": "Lacey Chabert", "character": "Gretchen Wieners"}, {"name": "Amanda Seyfried", "character": "Karen Smith"}]', 'Mark Waters', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (574, 'tt0458352', 350, 'The Devil Wears Prada', 2006, '/8912AsVuS7Sj915apArUFbv6F9L.jpg', '{18,35}', 'A young woman from the Midwest gets more than she bargained for when she moves to New York to become a writer and ends up as the assistant to the tyrannical, larger-than-life editor-in-chief of a major fashion magazine.', '[{"name": "Meryl Streep", "character": "Miranda Priestly"}, {"name": "Anne Hathaway", "character": "Andy Sachs"}, {"name": "Emily Blunt", "character": "Emily"}, {"name": "Stanley Tucci", "character": "Nigel"}, {"name": "Simon Baker", "character": "Christian Thompson"}]', 'David Frankel', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (575, 'tt0357413', 8699, 'Anchorman: The Legend of Ron Burgundy', 2004, '/mhZIcRePT7U8viFQVjt1ZjYIsR4.jpg', '{35}', 'It''s the 1970s and San Diego anchorman Ron Burgundy is the top dog in local TV, but that''s all about to change when ambitious reporter Veronica Corningstone arrives as a new employee at his station.', '[{"name": "Will Ferrell", "character": "Ron Burgundy"}, {"name": "Christina Applegate", "character": "Veronica Corningstone"}, {"name": "Paul Rudd", "character": "Brian Fantana"}, {"name": "Steve Carell", "character": "Brick Tamland"}, {"name": "David Koechner", "character": "Champ Kind"}]', 'Adam McKay', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (576, 'tt0351283', 953, 'Madagascar', 2005, '/zMpJY5CJKUufG9OTw0In4eAFqPX.jpg', '{12,16,35,10751}', 'Four animal friends get a taste of the wild life when they break out of captivity at the Central Park Zoo and wash ashore on the island of Madagascar.', '[{"name": "Ben Stiller", "character": "Alex (voice)"}, {"name": "Chris Rock", "character": "Marty (voice)"}, {"name": "David Schwimmer", "character": "Melman (voice)"}, {"name": "Jada Pinkett Smith", "character": "Gloria (voice)"}, {"name": "Sacha Baron Cohen", "character": "King Julien (voice)"}]', 'Eric Darnell', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (577, 'tt0317219', 920, 'Cars', 2006, '/2Touk3m5gzsqr1VsvxypdyHY5ci.jpg', '{16,12,35,10751}', 'Lightning McQueen, a hotshot rookie race car driven to succeed, discovers that life is about the journey, not the finish line, when he finds himself unexpectedly detoured in the sleepy Route 66 town of Radiator Springs. On route across the country to the big Piston Cup Championship in California to compete against two seasoned pros, McQueen gets to know the town''s offbeat characters.', '[{"name": "Owen Wilson", "character": "Lightning McQueen (voice)"}, {"name": "Paul Newman", "character": "Doc Hudson (voice)"}, {"name": "Bonnie Hunt", "character": "Sally Carrera (voice)"}, {"name": "Larry the Cable Guy", "character": "Mater (voice)"}, {"name": "Cheech Marin", "character": "Ramone (voice)"}]', 'John Lasseter', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (578, 'tt0418279', 1858, 'Transformers', 2007, '/4N4sipl8T72tNE4earcctQa2Kw2.jpg', '{12,878,28}', 'Young teenager Sam Witwicky becomes involved in the ancient struggle between two extraterrestrial factions of transforming robots – the heroic Autobots and the evil Decepticons. Sam holds the clue to unimaginable power and the Decepticons will stop at nothing to retrieve it.', '[{"name": "Shia LaBeouf", "character": "Sam Witwicky"}, {"name": "Megan Fox", "character": "Mikaela Banes"}, {"name": "Mark Ryan", "character": "Bumblebee (voice)"}, {"name": "Peter Cullen", "character": "Optimus Prime (voice)"}, {"name": "Hugo Weaving", "character": "Megatron (voice)"}]', 'Michael Bay', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (579, 'tt0829482', 8363, 'Superbad', 2007, '/ek8e8txUyUwd2BNqj6lFEerJfbq.jpg', '{35}', 'Two co-dependent high school seniors are forced to deal with separation anxiety after their plan to stage a booze-soaked party goes awry.', '[{"name": "Jonah Hill", "character": "Seth"}, {"name": "Michael Cera", "character": "Evan"}, {"name": "Christopher Mintz-Plasse", "character": "Fogell"}, {"name": "Bill Hader", "character": "Officer Slater"}, {"name": "Seth Rogen", "character": "Officer Michaels"}]', 'Greg Mottola', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (580, 'tt0441773', 9502, 'Kung Fu Panda', 2008, '/wWt4JYXTg5Wr3xBW2phBrMKgp3x.jpg', '{28,16,35,10751}', 'Chosen by prophecy but doubted by all, Po is an unlikely choice for the mystical title of the Dragon Warrior—a clumsy panda thrust into the world of kung fu as a deadly enemy threatens the Valley of Peace. Under reluctant guidance by Master Shifu and the Furious Five, Po must embrace who he is to unlock the power that no scroll can teach.', '[{"name": "Jack Black", "character": "Po (voice)"}, {"name": "Dustin Hoffman", "character": "Master Shifu (voice)"}, {"name": "Angelina Jolie", "character": "Tigress (voice)"}, {"name": "Ian McShane", "character": "Tai Lung (voice)"}, {"name": "Seth Rogen", "character": "Mantis (voice)"}]', 'Mark Osborne', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (581, 'tt1099212', 8966, 'Twilight', 2008, '/3Gkb6jm6962ADUPaCBqzz9CTbn9.jpg', '{14,18,10749}', 'When Bella Swan moves to a small town in the Pacific Northwest, she falls in love with Edward Cullen, a mysterious classmate who reveals himself to be a 108-year-old vampire. Despite Edward''s repeated cautions, Bella can''t stay away from him, a fatal move that endangers her own life.', '[{"name": "Kristen Stewart", "character": "Bella Swan"}, {"name": "Robert Pattinson", "character": "Edward Cullen"}, {"name": "Billy Burke", "character": "Charlie Swan"}, {"name": "Peter Facinelli", "character": "Dr. Carlisle Cullen"}, {"name": "Ashley Greene", "character": "Alice Cullen"}]', 'Catherine Hardwicke', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (582, 'tt1228705', 10138, 'Iron Man 2', 2010, '/6WBeq4fCfn7AN0o21W9qNcRF2l9.jpg', '{12,28,878}', 'With the world now aware of his dual life as the armored superhero Iron Man, billionaire inventor Tony Stark faces pressure from the government, the press and the public to share his technology with the military. Unwilling to let go of his invention, Stark, with Pepper Potts and James ''Rhodey'' Rhodes at his side, must forge new alliances – and confront powerful enemies.', '[{"name": "Robert Downey Jr.", "character": "Tony Stark"}, {"name": "Gwyneth Paltrow", "character": "Pepper Potts"}, {"name": "Don Cheadle", "character": "Lt. Col. James ''Rhodey'' Rhodes"}, {"name": "Scarlett Johansson", "character": "Natalie Rushman / Natasha Romanoff"}, {"name": "Sam Rockwell", "character": "Justin Hammer"}]', 'Jon Favreau', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (583, 'tt1323594', 20352, 'Despicable Me', 2010, '/b1BT309QWjtFUlJPLmXmrcHOWEL.jpg', '{16,35,80,878,10751}', 'Determined to prove he''s the world''s greatest supervillain, Gru hatches an audacious plan to steal the Moon. To pull it off, he adopts three orphaned girls—Margo, Edith, and Agnes—intending to use them as part of his scheme. But the unexpected bond they form forces him to question the life he''s always known.', '[{"name": "Steve Carell", "character": "Gru (voice)"}, {"name": "Jason Segel", "character": "Vector (voice)"}, {"name": "Russell Brand", "character": "Dr. Nefario (voice)"}, {"name": "Julie Andrews", "character": "Gru''s Mother (voice)"}, {"name": "Will Arnett", "character": "Mr. Perkins (voice)"}]', 'Pierre Coffin', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (584, 'tt0398286', 38757, 'Tangled', 2010, '/ym7Kst6a4uodryxqbGOxmewF235.jpg', '{16,10751,12}', 'Feisty teenager Rapunzel, who has long and magical hair, wants to go and see sky lanterns on her eighteenth birthday, but she''s bound to a tower by her overprotective mother. She strikes a deal with Flynn Rider, a charming wanted thief, and the duo set off on an action-packed escapade.', '[{"name": "Mandy Moore", "character": "Rapunzel (voice)"}, {"name": "Zachary Levi", "character": "Flynn Rider (voice)"}, {"name": "Donna Murphy", "character": "Mother Gothel (voice)"}, {"name": "Ron Perlman", "character": "Stabbington Brother (voice)"}, {"name": "M.C. Gainey", "character": "Captain of the Guard (voice)"}]', 'Byron Howard', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (585, 'tt1119646', 18785, 'The Hangover', 2009, '/A0uS9rHR56FeBtpjVki16M5xxSW.jpg', '{35}', 'When three friends finally come to after a raucous night of bachelor-party revelry, they find a baby in the closet and a tiger in the bathroom. But they can''t seem to locate their best friend, Doug – who''s supposed to be tying the knot. Launching a frantic search for Doug, the trio perseveres through a nasty hangover to try to make it to the church on time.', '[{"name": "Bradley Cooper", "character": "Phil Wenneck"}, {"name": "Ed Helms", "character": "Stu Price"}, {"name": "Zach Galifianakis", "character": "Alan Garner"}, {"name": "Justin Bartha", "character": "Doug Billings"}, {"name": "Heather Graham", "character": "Jade"}]', 'Todd Phillips', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (587, 'tt0800369', 10195, 'Thor', 2011, '/prSfAi1xGrhLQNxVSUFh61xQ4Qy.jpg', '{12,14,28}', 'Against his father Odin''s will, The Mighty Thor - a powerful but arrogant warrior god - recklessly reignites an ancient war. Thor is cast down to Earth and forced to live among humans as punishment. Once here, Thor learns what it takes to be a true hero when the most dangerous villain of his world sends the darkest forces of Asgard to invade Earth.', '[{"name": "Chris Hemsworth", "character": "Thor"}, {"name": "Natalie Portman", "character": "Jane Foster"}, {"name": "Tom Hiddleston", "character": "Loki"}, {"name": "Anthony Hopkins", "character": "Odin"}, {"name": "Stellan Skarsgård", "character": "Erik Selvig"}]', 'Kenneth Branagh', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (588, 'tt0458339', 1771, 'Captain America: The First Avenger', 2011, '/vSNxAJTlD0r02V9sPYpOjqDZXUK.jpg', '{28,12,878}', 'During World War II, Steve Rogers is a sickly man from Brooklyn who''s transformed into super-soldier Captain America to aid in the war effort. Rogers must stop the Red Skull – Adolf Hitler''s ruthless head of weaponry, and the leader of an organization that intends to use a mysterious device of untold powers for world domination.', '[{"name": "Chris Evans", "character": "Captain America / Steve Rogers"}, {"name": "Hayley Atwell", "character": "Peggy Carter"}, {"name": "Sebastian Stan", "character": "James Buchanan ''Bucky'' Barnes"}, {"name": "Tommy Lee Jones", "character": "Colonel Chester Phillips"}, {"name": "Hugo Weaving", "character": "Johann Schmidt / Red Skull"}]', 'Joe Johnston', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (589, 'tt1478338', 55721, 'Bridesmaids', 2011, '/gJtA7hYsBMQ7EM3sPBMUdBfU7a0.jpg', '{35,10749}', 'Annie''s life is a mess. But when she finds out her lifetime best friend is engaged, she simply must serve as Lillian''s maid of honor. Though lovelorn and broke, Annie bluffs her way through the expensive and bizarre rituals. With one chance to get it perfect, she’ll show Lillian and her bridesmaids just how far you’ll go for someone you love.', '[{"name": "Kristen Wiig", "character": "Annie"}, {"name": "Maya Rudolph", "character": "Lillian"}, {"name": "Rose Byrne", "character": "Helen"}, {"name": "Chris O''Dowd", "character": "Rhodes"}, {"name": "Melissa McCarthy", "character": "Megan"}]', 'Paul Feig', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (590, 'tt1229238', 56292, 'Mission: Impossible - Ghost Protocol', 2011, '/eRZTGx7GsiKqPch96k27LK005ZL.jpg', '{28,53,12}', 'Ethan Hunt and his team are racing against time to track down a dangerous terrorist named Hendricks, who has gained access to Russian nuclear launch codes and is planning a strike on the United States. An attempt to stop him ends in an explosion causing severe destruction to the Kremlin and the IMF to be implicated in the bombing, forcing the President to disavow them. No longer being aided by the government, Ethan and his team chase Hendricks around the globe, although they might still be too late to stop a disaster.', '[{"name": "Tom Cruise", "character": "Ethan Hunt"}, {"name": "Paula Patton", "character": "Jane"}, {"name": "Simon Pegg", "character": "Benji"}, {"name": "Jeremy Renner", "character": "Brandt"}, {"name": "Michael Nyqvist", "character": "Hendricks"}]', 'Brad Bird', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (591, 'tt1392170', 70160, 'The Hunger Games', 2012, '/yXCbOiVDCxO71zI7cuwBRXdftq8.jpg', '{878,12,28,53}', 'In a dystopian society where the Capitol forces each district to send two young tributes to fight to the death in a televised spectacle, a girl volunteers to take her sister’s place, setting the stage for a struggle of survival and defiance.', '[{"name": "Jennifer Lawrence", "character": "Katniss Everdeen"}, {"name": "Josh Hutcherson", "character": "Peeta Mellark"}, {"name": "Liam Hemsworth", "character": "Gale Hawthorne"}, {"name": "Woody Harrelson", "character": "Haymitch Abernathy"}, {"name": "Elizabeth Banks", "character": "Effie Trinket"}]', 'Gary Ross', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (592, 'tt0948470', 1930, 'The Amazing Spider-Man', 2012, '/jexoNYnPd6vVrmygwF6QZmWPFdu.jpg', '{28,12,878}', 'Peter Parker is an outcast high schooler abandoned by his parents as a boy, leaving him to be raised by his Uncle Ben and Aunt May. Like most teenagers, Peter is trying to figure out who he is and how he got to be the person he is today. As Peter discovers a mysterious briefcase that belonged to his father, he begins a quest to understand his parents'' disappearance – leading him directly to Oscorp and the lab of Dr. Curt Connors, his father''s former partner. As Spider-Man is set on a collision course with Connors'' alter ego, The Lizard, Peter will make life-altering choices to use his powers and shape his destiny to become a hero.', '[{"name": "Andrew Garfield", "character": "Spider-Man / Peter Parker"}, {"name": "Emma Stone", "character": "Gwen Stacy"}, {"name": "Rhys Ifans", "character": "The Lizard / Dr. Curt Connors"}, {"name": "Denis Leary", "character": "Captain Stacy"}, {"name": "Martin Sheen", "character": "Uncle Ben"}]', 'Marc Webb', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (593, 'tt1217209', 62177, 'Brave', 2012, '/1XAuDtMWpL0sYSFK0R6EZate2Ux.jpg', '{12,16,10751,14}', 'In the mystical Scottish Highlands, Merida is the princess of a kingdom ruled by King Fergus and Queen Elinor. An unruly daughter and an accomplished archer, Merida one day defies a sacred custom of the land and inadvertently brings turmoil to the kingdom. In an attempt to set things right, Merida seeks out an eccentric old Wise Woman and is granted an ill-fated wish. Also figuring into Merida''s quest- and serving as comic relief- are the kingdom''s three lords: the enormous Lord MacGuffin, the surly Lord Macintosh, and the disagreeable Lord Dingwall.', '[{"name": "Kelly Macdonald", "character": "Merida (voice)"}, {"name": "Emma Thompson", "character": "Elinor (voice)"}, {"name": "Billy Connolly", "character": "Fergus (voice)"}, {"name": "Julie Walters", "character": "The Witch (voice)"}, {"name": "Robbie Coltrane", "character": "Lord Dingwall (voice)"}]', 'Mark Andrews', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (594, 'tt1772341', 82690, 'Wreck-It Ralph', 2012, '/ihfvxPh5C4rV2WSKWs7k7rzxzzO.jpg', '{10751,16,35,12}', 'Wreck-It Ralph is the 9-foot-tall, 643-pound villain of an arcade video game named Fix-It Felix Jr., in which the game''s titular hero fixes buildings that Ralph destroys. Wanting to prove he can be a good guy and not just a villain, Ralph escapes his game and lands in Hero''s Duty, a first-person shooter where he helps the game''s hero battle against alien invaders. He later enters Sugar Rush, a kart racing game set on tracks made of candies, cookies and other sweets. There, Ralph meets Vanellope von Schweetz who has learned that her game is faced with a dire threat that could affect the entire arcade, and one that Ralph may have inadvertently started.', '[{"name": "John C. Reilly", "character": "Ralph (voice)"}, {"name": "Sarah Silverman", "character": "Vanellope (voice)"}, {"name": "Jack McBrayer", "character": "Felix (voice)"}, {"name": "Jane Lynch", "character": "Calhoun (voice)"}, {"name": "Alan Tudyk", "character": "King Candy (voice)"}]', 'Rich Moore', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (595, 'tt1300854', 68721, 'Iron Man 3', 2013, '/qhPtAc1TKbMPqNvcdXSOn9Bn7hZ.jpg', '{28,12,878}', 'When Tony Stark''s world is torn apart by a formidable terrorist called the Mandarin, he starts an odyssey of rebuilding and retribution.', '[{"name": "Robert Downey Jr.", "character": "Tony Stark"}, {"name": "Gwyneth Paltrow", "character": "Pepper Potts"}, {"name": "Don Cheadle", "character": "Colonel James Rhodes"}, {"name": "Guy Pearce", "character": "Aldrich Killian"}, {"name": "Rebecca Hall", "character": "Maya Hansen"}]', 'Shane Black', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (596, 'tt0816711', 72190, 'World War Z', 2013, '/aCnVdvExw6UWSeQfr0tUH3jr4qG.jpg', '{28,27,878}', 'Life for former United Nations investigator Gerry Lane and his family seems content. Suddenly, the world is plagued by a mysterious infection turning whole human populations into rampaging mindless zombies. After barely escaping the chaos, Lane is persuaded to go on a mission to investigate this disease. What follows is a perilous trek around the world where Lane must brave horrific dangers and long odds to find answers before human civilization falls.', '[{"name": "Brad Pitt", "character": "Gerry Lane"}, {"name": "Mireille Enos", "character": "Karen Lane"}, {"name": "Daniella Kertesz", "character": "Segen"}, {"name": "James Badge Dale", "character": "Captain Speke"}, {"name": "Ludi Boeken", "character": "Jurgen Warmbrunn"}]', 'Marc Forster', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (597, 'tt2294629', 109445, 'Frozen', 2013, '/itAKcobTYGpYT8Phwjd8c9hleTo.jpg', '{16,10751,12,14}', 'Young princess Anna of Arendelle dreams about finding true love at her sister Elsa’s coronation. Fate takes her on a dangerous journey in an attempt to end the eternal winter that has fallen over the kingdom. She''s accompanied by ice delivery man Kristoff, his reindeer Sven, and snowman Olaf. On an adventure where she will find out what friendship, courage, family, and true love really means.', '[{"name": "Idina Menzel", "character": "Elsa (voice)"}, {"name": "Kristen Bell", "character": "Anna (voice)"}, {"name": "Jonathan Groff", "character": "Kristoff (voice)"}, {"name": "Josh Gad", "character": "Olaf (voice)"}, {"name": "Livvy Stubenrauch", "character": "Young Anna (voice)"}]', 'Chris Buck', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (598, 'tt0770828', 49521, 'Man of Steel', 2013, '/8GFtkImmK0K1VaUChR0n9O61CFU.jpg', '{28,12,878}', 'A young boy learns that he has extraordinary powers and is not of this earth. As a young man, he journeys to discover where he came from and what he was sent here to do. But the hero in him must emerge if he is to save the world from annihilation and become the symbol of hope for all mankind.', '[{"name": "Henry Cavill", "character": "Clark Kent / Kal-El"}, {"name": "Amy Adams", "character": "Lois Lane"}, {"name": "Michael Shannon", "character": "General Zod"}, {"name": "Diane Lane", "character": "Martha Kent"}, {"name": "Russell Crowe", "character": "Jor-El"}]', 'Zack Snyder', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (599, 'tt1457767', 138843, 'The Conjuring', 2013, '/wVYREutTvI2tmxr6ujrHT704wGF.jpg', '{27,53}', 'Paranormal investigators Ed and Lorraine Warren work to help a family terrorized by a dark presence in their farmhouse. Forced to confront a powerful entity, the Warrens find themselves caught in the most terrifying case of their lives.', '[{"name": "Vera Farmiga", "character": "Lorraine Warren"}, {"name": "Patrick Wilson", "character": "Ed Warren"}, {"name": "Lili Taylor", "character": "Carolyn Perron"}, {"name": "Ron Livingston", "character": "Roger Perron"}, {"name": "Hayley McFarland", "character": "Nancy"}]', 'James Wan', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (600, 'tt1596343', 51497, 'Fast Five', 2011, '/gEfQjjQwY7fh5bI4GlG0RrBu7Pz.jpg', '{28,53,80}', 'Former cop Brian O''Conner partners with ex-con Dom Toretto on the opposite side of the law. Since Brian and Mia Toretto broke Dom out of custody, they''ve blown across many borders to elude authorities. Now backed into a corner in Rio de Janeiro, they must pull one last job in order to gain their freedom.', '[{"name": "Vin Diesel", "character": "Dominic Toretto"}, {"name": "Paul Walker", "character": "Brian O''Conner"}, {"name": "Jordana Brewster", "character": "Mia Toretto"}, {"name": "Tyrese Gibson", "character": "Roman Pearce"}, {"name": "Ludacris", "character": "Tej Parker"}]', 'Justin Lin', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (601, 'tt1340138', 87101, 'Terminator Genisys', 2015, '/oZRVDpNtmHk8M1VYy1aeOWUXgbC.jpg', '{878,28,53}', 'The year is 2029. John Connor, leader of the resistance continues the war against the machines. At the Los Angeles offensive, John''s fears of the unknown future begin to emerge when TECOM spies reveal a new plot by SkyNet that will attack him from both fronts; past and future, and will ultimately change warfare forever.', '[{"name": "Emilia Clarke", "character": "Sarah Connor"}, {"name": "Jai Courtney", "character": "Kyle Reese"}, {"name": "Arnold Schwarzenegger", "character": "Guardian / The Terminator"}, {"name": "Jason Clarke", "character": "John Connor"}, {"name": "Matt Smith", "character": "Alex / Skynet"}]', 'Alan Taylor', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (602, 'tt0369610', 135397, 'Jurassic World', 2015, '/rhr4y79GpxQF9IsfJItRXVaoGs4.jpg', '{12,878,53}', 'Twenty-two years after the events of Jurassic Park, Isla Nublar now features a fully functioning dinosaur theme park, Jurassic World, as originally envisioned by John Hammond.', '[{"name": "Chris Pratt", "character": "Owen"}, {"name": "Bryce Dallas Howard", "character": "Claire"}, {"name": "Irrfan Khan", "character": "Masrani"}, {"name": "Vincent D''Onofrio", "character": "Hoskins"}, {"name": "Ty Simpkins", "character": "Gray"}]', 'Colin Trevorrow', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (603, 'tt0478970', 102899, 'Ant-Man', 2015, '/rQRnQfUl3kfp78nCWq8Ks04vnq1.jpg', '{878,12,28}', 'Armed with the astonishing ability to shrink in scale but increase in strength, master thief Scott Lang must embrace his inner-hero and help his mentor, Doctor Hank Pym, protect the secret behind his spectacular Ant-Man suit from a new generation of towering threats. Against seemingly insurmountable obstacles, Pym and Lang must plan and pull off a heist that will save the world.', '[{"name": "Paul Rudd", "character": "Scott Lang / Ant-Man"}, {"name": "Michael Douglas", "character": "Dr. Hank Pym"}, {"name": "Evangeline Lilly", "character": "Hope van Dyne"}, {"name": "Corey Stoll", "character": "Darren Cross / Yellowjacket"}, {"name": "Bobby Cannavale", "character": "Paxton"}]', 'Peyton Reed', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (586, 'tt1155076', 38575, 'The Karate Kid', 2010, '/b1RBy3l297N0c7PHjlz35cClWju.jpg', '{28,12,18,10751}', '12-year-old Dre Parker could''ve been the most popular kid in Detroit, but his mother''s latest career move has landed him in China. Dre immediately falls for his classmate Mei Ying but the cultural differences make such a friendship impossible. Even worse, Dre''s feelings make him an enemy of the class bully, Cheng. With no friends in a strange land, Dre has nowhere to turn but maintenance man Mr. Han, who is a kung fu master. As Han teaches Dre that kung fu is not about punches and parries, but maturity and calm, Dre realizes that facing down the bullies will be the fight of his life.', '[{"name": "Jaden Smith", "character": "Dre Parker"}, {"name": "Jackie Chan", "character": "Mr. Han"}, {"name": "Taraji P. Henson", "character": "Sherry Parker"}, {"name": "Wenwen Han", "character": "Meiying"}, {"name": "Zac Wang", "character": "Cheng"}]', 'Harald Zwart', NULL, '2026-07-22 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (604, 'tt0212338', 1597, 'Meet the Parents', 2000, '/5tXJ9ctuyEOMUFLaeqRisbXowWs.jpg', '{35,10749}', 'Greg Focker is ready to marry his girlfriend, Pam, but before he pops the question, he must win over her formidable father, humorless former CIA agent Jack Byrnes, at the wedding of Pam''s sister. As Greg bends over backward to make a good impression, his visit to the Byrnes home turns into a hilarious series of disasters, and everything that can go wrong does, all under Jack''s critical, hawklike gaze.', '[{"name":"Ben Stiller","character":"Greg Focker"},{"name":"Robert De Niro","character":"Jack Byrnes"},{"name":"Teri Polo","character":"Pam Byrnes"},{"name":"Blythe Danner","character":"Dina Byrnes"},{"name":"Nicole DeHuff","character":"Debbie Byrnes"}]', 'Jay Roach', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (605, 'tt0212346', 1493, 'Miss Congeniality', 2000, '/pat3vKaRlB70he4ghwTMydR4TvP.jpg', '{35,80,28}', 'When the local FBI office receives a letter from a terrorist known only as ''The Citizen'', it''s quickly determined that he''s planning his next act at the Miss America beauty pageant. Because tough-as-nails Gracie Hart is the only female Agent at the office, she''s chosen to go undercover as the contestant from New Jersey.', '[{"name":"Sandra Bullock","character":"Gracie Hart"},{"name":"Benjamin Bratt","character":"Eric Matthews"},{"name":"Heather Burns","character":"Cheryl Frasier"},{"name":"Michael Caine","character":"Victor Melling"},{"name":"Ernie Hudson","character":"Harry McDonald"}]', 'Donald Petrie', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (606, 'tt0243155', 634, 'Bridget Jones''s Diary', 2001, '/olMTi7uCaec9Yr3Ar07D2SIja1G.jpg', '{35,10749,18}', 'Bridget Jones is an average woman struggling against expectations. As a New Year''s resolution, Bridget decides to take control of her life, starting by keeping a diary in which she will always tell the complete truth. Her charming boss takes an interest in her, and she cannot stop running into a rather disagreeable acquaintance whom Bridget cannot help finding quietly attractive.', '[{"name":"Renée Zellweger","character":"Bridget Jones"},{"name":"Colin Firth","character":"Mark Darcy"},{"name":"Hugh Grant","character":"Daniel Cleaver"},{"name":"Jim Broadbent","character":"Bridget''s Dad"},{"name":"Gemma Jones","character":"Bridget''s Mum"}]', 'Sharon Maguire', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (607, 'tt0266915', 5175, 'Rush Hour 2', 2001, '/aBQf2vMiCINeVC9v6BGVYKXurTh.jpg', '{28,35,80}', 'It''s vacation time for Carter as he finds himself alongside Lee in Hong Kong wishing for more excitement. While Carter wants to party and meet the ladies, Lee is out to track down a Triad gang lord who may be responsible for killing two men at the American Embassy. Things get complicated as the pair stumble onto a counterfeiting plot. The boys are soon up to their necks in fist fights and life-threatening situations. A trip back to the U.S. may provide the answers about the bombing, the counterfeiting, and the true allegiance of sexy customs agent Isabella.', '[{"name":"Jackie Chan","character":"Yan Naing Lee"},{"name":"Chris Tucker","character":"James Carter"},{"name":"John Lone","character":"Ricky Tan"},{"name":"Roselyn Sánchez","character":"Isabella Molina"},{"name":"Zhang Ziyi","character":"Hu Li"}]', 'Brett Ratner', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (608, 'tt0315327', 310, 'Bruce Almighty', 2003, '/wqkWrOFtYnZSvIMu8Lsmz7WIvKC.jpg', '{14,35}', 'Bruce Nolan toils as a "human interest" television reporter in Buffalo, NY, but despite his high ratings and the love of his beautiful girlfriend, Bruce remains unfulfilled. At the end of the worst day in his life, he angrily ridicules God- and the Almighty responds, endowing Bruce with all of His divine powers.', '[{"name":"Jim Carrey","character":"Bruce Nolan"},{"name":"Morgan Freeman","character":"God"},{"name":"Jennifer Aniston","character":"Grace Connelly"},{"name":"Philip Baker Hall","character":"Jack Baylor"},{"name":"Catherine Bell","character":"Susan Ortega"}]', 'Tom Shadyac', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (609, 'tt0322330', 10330, 'Freaky Friday', 2003, '/ipKcZ4Up7dp18XpsfYUc9NKZy3g.jpg', '{35,10751,14}', 'Mother and daughter bicker over everything -- what Anna wears, whom she likes and what she wants to do when she''s older. In turn, Anna detests Tess''s fiancé. When a magical fortune cookie switches their personalities, they each get a peek at how the other person feels, thinks and lives.', '[{"name":"Lindsay Lohan","character":"Anna Coleman"},{"name":"Jamie Lee Curtis","character":"Tess Coleman"},{"name":"Harold Gould","character":"Grandpa"},{"name":"Chad Michael Murray","character":"Jake"},{"name":"Mark Harmon","character":"Ryan"}]', 'Mark Waters', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (610, 'tt0368891', 2059, 'National Treasure', 2004, '/pxL6E4GBOPUG6CdkO9cUQN5VMwI.jpg', '{12,28,9648}', 'Modern treasure hunters, led by archaeologist Ben Gates, search for a chest of riches rumored to have been stashed away by George Washington, Thomas Jefferson and Benjamin Franklin during the Revolutionary War. The chest''s whereabouts may lie in secret clues embedded in the Constitution and the Declaration of Independence, and Gates is in a race to find the gold before his enemies do.', '[{"name":"Nicolas Cage","character":"Benjamin Franklin Gates"},{"name":"Diane Kruger","character":"Abigail Chase"},{"name":"Justin Bartha","character":"Riley Poole"},{"name":"Sean Bean","character":"Ian Howe"},{"name":"Jon Voight","character":"Patrick Gates"}]', 'Jon Turteltaub', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (611, 'tt0396269', 9522, 'Wedding Crashers', 2005, '/lFM3lk2zVzC1YFnKm0r6LbFPyRu.jpg', '{35,10749}', 'John and his buddy Jeremy are emotional criminals who know how to use a woman''s hopes and dreams for their own carnal gain. Their modus operandi: crashing weddings. Normally, they meet guests who want to toast the romantic day with a random hook-up. But when John meets Claire, he discovers what true love – and heartache – feels like.', '[{"name":"Owen Wilson","character":"John Beckwith"},{"name":"Vince Vaughn","character":"Jeremy Grey"},{"name":"Christopher Walken","character":"Secretary Cleary"},{"name":"Rachel McAdams","character":"Claire Cleary"},{"name":"Isla Fisher","character":"Gloria Cleary"}]', 'David Dobkin', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (612, 'tt0382625', 591, 'The Da Vinci Code', 2006, '/9ejKfNk0LBhSI9AahH4f9NJNZNM.jpg', '{53,9648}', 'A murder in Paris’ Louvre Museum and cryptic clues in some of Leonardo da Vinci’s most famous paintings lead to the discovery of a religious mystery. For 2,000 years a secret society closely guards information that- should it come to light- could rock the very foundations of Christianity.', '[{"name":"Tom Hanks","character":"Robert Langdon"},{"name":"Audrey Tautou","character":"Sophie Neveu"},{"name":"Ian McKellen","character":"Sir Leigh Teabing"},{"name":"Jean Reno","character":"Captain Bezu Fache"},{"name":"Paul Bettany","character":"Silas"}]', 'Ron Howard', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (613, 'tt0477347', 1593, 'Night at the Museum', 2006, '/pDsAAYf6Zn0yiAGJ6lYGs6hoZ4E.jpg', '{14,10751,35}', 'Chaos reigns at the natural history museum when night watchman Larry Daley accidentally stirs up an ancient curse, awakening Attila the Hun, an army of gladiators, a Tyrannosaurus rex and other exhibits.', '[{"name":"Ben Stiller","character":"Larry Daley"},{"name":"Carla Gugino","character":"Rebecca"},{"name":"Dick Van Dyke","character":"Cecil"},{"name":"Mickey Rooney","character":"Gus"},{"name":"Bill Cobbs","character":"Reginald"}]', 'Shawn Levy', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (614, 'tt0480249', 6479, 'I Am Legend', 2007, '/iPDkaSdKk2jRLTM65UOEoKtsIZ8.jpg', '{18,878,53}', 'Robert Neville is a scientist who was unable to stop the spread of the terrible virus that was incurable and man-made. Immune, Neville is now the last human survivor in what is left of New York City and perhaps the world. For three years, Neville has faithfully sent out daily radio messages, desperate to find any other survivors who might be out there. But he is not alone.', '[{"name":"Will Smith","character":"Robert Neville"},{"name":"Alice Braga","character":"Anna Montez"},{"name":"Charlie Tahan","character":"Ethan"},{"name":"Dash Mihok","character":"Alpha Male"},{"name":"Salli Richardson-Whitfield","character":"Zoe Neville"}]', 'Francis Lawrence', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (615, 'tt0461770', 4523, 'Enchanted', 2007, '/8KCNzCArLlvLdQoHx6npua2VSVc.jpg', '{35,10751,14,10749}', 'The beautiful princess Giselle is banished by an evil queen from her magical, musical animated land and finds herself in the gritty reality of the streets of modern-day Manhattan. Shocked by this strange new environment that doesn''t operate on a "happily ever after" basis, Giselle is now adrift in a chaotic world badly in need of enchantment. But when Giselle begins to fall in love with a charmingly flawed divorce lawyer who has come to her aid - even though she is already promised to a perfect fairy tale prince back home - she has to wonder: Can a storybook view of romance survive in the real world?', '[{"name":"Amy Adams","character":"Giselle"},{"name":"Patrick Dempsey","character":"Robert Philip"},{"name":"James Marsden","character":"Prince Edward"},{"name":"Timothy Spall","character":"Nathaniel"},{"name":"Idina Menzel","character":"Nancy Tremaine"}]', 'Kevin Lima', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (616, 'tt0795421', 11631, 'Mamma Mia!', 2008, '/zdUA4FNHbXPadzVOJiU0Rgn6cHR.jpg', '{35,10749}', 'A spirited young bride-to-be living with her single mother on a small Greek island secretly invites three of her mother''s ex-boyfriends in hope of finding her biological father to walk her down the aisle.', '[{"name":"Amanda Seyfried","character":"Sophie Sheridan"},{"name":"Meryl Streep","character":"Donna Sheridan"},{"name":"Pierce Brosnan","character":"Sam Carmichael"},{"name":"Colin Firth","character":"Harry Bright"},{"name":"Stellan Skarsgård","character":"Bill Anderson"}]', 'Phyllida Lloyd', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (617, 'tt1000774', 4564, 'Sex and the City', 2008, '/AhNfnsGW95RKHQNLdgFH48UN0Zy.jpg', '{35,18,10749}', 'When Carrie''s big step forward in her relationship goes awry, best friends Charlotte, Miranda and Samantha are there to help her pick up the pieces.', '[{"name":"Sarah Jessica Parker","character":"Carrie Bradshaw"},{"name":"Kim Cattrall","character":"Samantha Jones"},{"name":"Kristin Davis","character":"Charlotte York"},{"name":"Cynthia Nixon","character":"Miranda Hobbes"},{"name":"Chris Noth","character":"Mr. Big"}]', 'Michael Patrick King', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (618, 'tt1041829', 18240, 'The Proposal', 2009, '/6stnAm1wSek8ZrislwK4xGTyCnt.jpg', '{35,10749,18}', 'When she learns she''s in danger of losing her visa status and being deported, overbearing book editor Margaret Tate forces her put-upon assistant, Andrew Paxton, to marry her.', '[{"name":"Sandra Bullock","character":"Margaret Tate"},{"name":"Ryan Reynolds","character":"Andrew Paxton"},{"name":"Malin Åkerman","character":"Gertrude"},{"name":"Craig T. Nelson","character":"Joe Paxton"},{"name":"Mary Steenburgen","character":"Grace Paxton"}]', 'Anne Fletcher', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (619, 'tt1093908', 20048, 'Confessions of a Shopaholic', 2009, '/r17R9OIC0pKDqqsNore6atYLCVZ.jpg', '{35,10749}', 'In the glamorous world of New York City, Rebecca Bloomwood is a fun-loving girl who is really good at shopping – a little too good, perhaps. She dreams of working for her favorite fashion magazine, but can''t quite get her foot in the door – until ironically, she snags a job as an advice columnist for a financial magazine published by the same company.', '[{"name":"Isla Fisher","character":"Rebecca Bloomwood"},{"name":"Hugh Dancy","character":"Luke Brandon"},{"name":"Krysten Ritter","character":"Suze"},{"name":"Joan Cusack","character":"Jane Bloomwood"},{"name":"John Goodman","character":"Graham Bloomwood"}]', 'P.J. Hogan', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (620, 'tt0988045', 10528, 'Sherlock Holmes', 2009, '/momkKuWburNTqKBF6ez7rvhYVhE.jpg', '{28,12,9648}', 'Eccentric consulting detective Sherlock Holmes and Doctor John Watson battle to bring down a new nemesis and unravel a deadly plot that could destroy England.', '[{"name":"Robert Downey Jr.","character":"Sherlock Holmes"},{"name":"Jude Law","character":"Dr. John Watson"},{"name":"Rachel McAdams","character":"Irene Adler"},{"name":"Mark Strong","character":"Lord Henry Blackwood"},{"name":"Eddie Marsan","character":"Inspector Lestrade"}]', 'Guy Ritchie', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (621, 'tt1570728', 50646, 'Crazy, Stupid, Love.', 2011, '/p4RafgAPk558muOjnBMHhMArjS2.jpg', '{35,18,10749}', 'Cal Weaver is living the American dream. He has a good job, a beautiful house, great children and a beautiful wife, named Emily. Cal''s seemingly perfect life unravels, however, when he learns that Emily has been unfaithful and wants a divorce. Over 40 and suddenly single, Cal is adrift in the fickle world of dating. Enter, Jacob Palmer, a self-styled player who takes Cal under his wing and teaches him how to be a hit with the ladies.', '[{"name":"Steve Carell","character":"Cal"},{"name":"Ryan Gosling","character":"Jacob"},{"name":"Julianne Moore","character":"Emily"},{"name":"Emma Stone","character":"Hannah"},{"name":"Lio Tipton","character":"Jessica"}]', 'Glenn Ficarra', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (622, 'tt1981677', 114150, 'Pitch Perfect', 2012, '/gsFoJk9g8W3zgaipRrrURk7LbiF.jpg', '{35,10402,10749}', 'College student Beca knows she does not want to be part of a clique, but that''s exactly where she finds herself after arriving at her new school. Thrust in among mean gals, nice gals and just plain weird gals, Beca finds that the only thing they have in common is how well they sing together. She takes the women of the group out of their comfort zone of traditional arrangements and into a world of amazing harmonic combinations in a fight to the top of college music competitions.', '[{"name":"Anna Kendrick","character":"Beca Mitchell"},{"name":"Anna Camp","character":"Aubrey Posen"},{"name":"Brittany Snow","character":"Chloe Beale"},{"name":"Skylar Astin","character":"Jesse Swanson"},{"name":"Rebel Wilson","character":"Fat Amy"}]', 'Jason Moore', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (623, 'tt1637725', 72105, 'Ted', 2012, '/1QVZXQQHCEIj8lyUhdBYd2qOYtq.jpg', '{35,14}', 'John Bennett, a man whose childhood wish of bringing his teddy bear to life came true, now must decide between keeping the relationship with the bear or his girlfriend, Lori.', '[{"name":"Mark Wahlberg","character":"John Bennett"},{"name":"Mila Kunis","character":"Lori Collins"},{"name":"Seth MacFarlane","character":"Ted (voice)"},{"name":"Joel McHale","character":"Rex"},{"name":"Giovanni Ribisi","character":"Donny"}]', 'Seth MacFarlane', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (624, 'tt1232829', 64688, '21 Jump Street', 2012, '/8v3Sqv9UcIUC4ebmpKWROqPBINZ.jpg', '{28,35,80}', 'When cops Schmidt and Jenko join the secret Jump Street unit, they use their youthful appearances to go undercover as high school students. They trade in their guns and badges for backpacks, and set out to shut down a dangerous drug ring. But, as time goes on, Schmidt and Jenko discover that high school is nothing like it was just a few years earlier -- and, what''s more, they must again confront the teenage terror and anxiety they thought they had left behind.', '[{"name":"Jonah Hill","character":"Schmidt"},{"name":"Channing Tatum","character":"Jenko"},{"name":"Brie Larson","character":"Molly Tracey"},{"name":"Dave Franco","character":"Eric Molson"},{"name":"Rob Riggle","character":"Mr. Walters"}]', 'Phil Lord', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (625, 'tt1670345', 75656, 'Now You See Me', 2013, '/tWsNYbrqy1p1w6K9zRk0mSchztT.jpg', '{53,80}', 'An FBI agent and an Interpol detective track a team of illusionists who pull off bank heists during their performances and reward their audiences with the money.', '[{"name":"Jesse Eisenberg","character":"J. Daniel Atlas"},{"name":"Woody Harrelson","character":"Merritt McKinney"},{"name":"Isla Fisher","character":"Henley Reeves"},{"name":"Dave Franco","character":"Jack Wilder"},{"name":"Mark Ruffalo","character":"Dylan Rhodes"}]', 'Louis Leterrier', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (626, 'tt2322441', 216015, 'Fifty Shades of Grey', 2015, '/63kGofUkt1Mx0SIL4XI4Z5AoSgt.jpg', '{18,10749,53}', 'When college senior Anastasia Steele steps in for her sick roommate to interview prominent businessman Christian Grey for their campus paper, little does she realize the path her life will take. Christian, as enigmatic as he is rich and powerful, finds himself strangely drawn to Ana, and she to him. Though sexually inexperienced, Ana plunges headlong into an affair -- and learns that Christian''s true sexual proclivities push the boundaries of pain and pleasure.', '[{"name":"Dakota Johnson","character":"Anastasia Steele"},{"name":"Jamie Dornan","character":"Christian Grey"},{"name":"Jennifer Ehle","character":"Carla"},{"name":"Eloise Mumford","character":"Kate"},{"name":"Victor Rasuk","character":"José"}]', 'Sam Taylor-Johnson', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (627, 'tt1489889', 302699, 'Central Intelligence', 2016, '/hXQVMbRNpf7c93e8clMY4W5DRm6.jpg', '{28,35}', 'Calvin Joyner, a mild-mannered accountant whose high school glory days are long behind him, reconnects with an awkward pal from high school through Facebook. After meeting up, Calvin’s mundane life takes an unexpectedly thrilling turn when he''s thrust into the world of international espionage.', '[{"name":"Dwayne Johnson","character":"Bob Stone"},{"name":"Kevin Hart","character":"Calvin Joyner"},{"name":"Amy Ryan","character":"Pamela Harris"},{"name":"Danielle Nicolet","character":"Maggie"},{"name":"Jason Bateman","character":"Trevor"}]', 'Rawson Marshall Thurber', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (628, 'tt3470600', 335797, 'Sing', 2016, '/rwopfpHqPCYBSgBuZwkaXXqHp14.jpg', '{16,35,10751,10402}', 'A koala named Buster recruits his best friend to help him drum up business for his theater by hosting a singing competition.', '[{"name":"Matthew McConaughey","character":"Buster Moon (voice)"},{"name":"Reese Witherspoon","character":"Rosita (voice)"},{"name":"Seth MacFarlane","character":"Mike (voice)"},{"name":"Scarlett Johansson","character":"Ash (voice)"},{"name":"John C. Reilly","character":"Eddie (voice)"}]', 'Garth Jennings', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (629, 'tt3890160', 339403, 'Baby Driver', 2017, '/tYzFuYXmT8LOYASlFCkaPiAFAl0.jpg', '{28,80}', 'After being coerced into working for a crime boss, a young getaway driver finds himself taking part in a heist doomed to fail.', '[{"name":"Ansel Elgort","character":"Baby"},{"name":"Kevin Spacey","character":"Doc"},{"name":"Lily James","character":"Debora"},{"name":"Jon Hamm","character":"Buddy"},{"name":"Jamie Foxx","character":"Bats"}]', 'Edgar Wright', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (630, 'tt3104988', 455207, 'Crazy Rich Asians', 2018, '/1XxL4LJ5WHdrcYcihEZUCgNCpAW.jpg', '{35,10749}', 'An American-born Chinese economics professor accompanies her boyfriend to Singapore for his best friend''s wedding, only to get thrust into the lives of Asia''s rich and famous.', '[{"name":"Constance Wu","character":"Rachel Chu"},{"name":"Henry Golding","character":"Nick Young"},{"name":"Michelle Yeoh","character":"Eleanor Young"},{"name":"Gemma Chan","character":"Astrid Young Teo"},{"name":"Lisa Lu","character":"Ah Ma"}]', 'Jon M. Chu', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (631, 'tt0386588', 8488, 'Hitch', 2005, '/x3W9H3nhGQbWSlyI8Amp2F6Z6cz.jpg', '{35,18,10749}', 'Dating coach Alex ''Hitch'' Hitchens mentors a bumbling client, Albert, who hopes to win the heart of the glamorous Allegra Cole. While Albert makes progress, Hitch faces his own romantic setbacks when proven techniques fail to work on Sara Melas, a tabloid reporter digging for dirt on Allegra Cole''s love life. When Sara discovers Hitch''s connection to Albert – now Allegra''s boyfriend – it threatens to destroy both relationships.', '[{"name":"Will Smith","character":"Hitch"},{"name":"Eva Mendes","character":"Sara"},{"name":"Kevin James","character":"Albert"},{"name":"Amber Valletta","character":"Allegra"},{"name":"Julie Ann Emery","character":"Casey"}]', 'Andy Tennant', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (632, 'tt0383574', 58, 'Pirates of the Caribbean: Dead Man''s Chest', 2006, '/uXEqmloGyP7UXAiphJUu2v2pcuE.jpg', '{12,14,28}', 'Captain Jack Sparrow’s got a blood debt to pay: he owes his soul to the legendary Davy Jones, ghastly Ruler of the Ocean Depths. To escape eternal servitude aboard the Flying Dutchman, ever-crafty Jack must track down the still-beating heart of Jones. But he won’t do it alone: Will Turner and Elizabeth Swann are drawn back into another one of his perilous quests—assuming they can evade execution for aiding a pirate.', '[{"name":"Johnny Depp","character":"Jack Sparrow"},{"name":"Orlando Bloom","character":"Will Turner"},{"name":"Keira Knightley","character":"Elizabeth Swann"},{"name":"Jack Davenport","character":"Norrington"},{"name":"Bill Nighy","character":"Davy Jones"}]', 'Gore Verbinski', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (633, 'tt0281358', 10229, 'A Walk to Remember', 2002, '/8lUYMvWdHA0Q0k5F76RQCeCBUkA.jpg', '{18,10749}', 'When the popular, restless Landon Carter is forced to participate in the school drama production, he falls in love with Jamie Sullivan, the daughter of the town''s minister. Jamie has a "to-do" list for her life, as well as a very big secret she must keep from Landon.', '[{"name":"Mandy Moore","character":"Jamie Sullivan"},{"name":"Shane West","character":"Landon Carter"},{"name":"Peter Coyote","character":"Reverend Sullivan"},{"name":"Daryl Hannah","character":"Cynthia Carter"},{"name":"Lauren German","character":"Belinda"}]', 'Adam Shankman', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (634, 'tt2283362', 353486, 'Jumanji: Welcome to the Jungle', 2017, '/pSgXKPU5h6U89ipF7HBYajvYt7j.jpg', '{12,35,14,28}', 'Four teenagers in detention discover an old video game console with a game they’ve never heard of. When they decide to play, they are immediately sucked into the jungle world of Jumanji in the bodies of their avatars. They’ll have to complete the adventure of their lives filled with fun, thrills and danger or be stuck in the game forever!', '[{"name":"Dwayne Johnson","character":"Dr. Smolder Bravestone"},{"name":"Kevin Hart","character":"Franklin ''Mouse'' Finbar"},{"name":"Jack Black","character":"Professor Sheldon ''Shelly'' Oberon"},{"name":"Karen Gillan","character":"Ruby Roundhouse"},{"name":"Rhys Darby","character":"Nigel Billingsley"}]', 'Jake Kasdan', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (635, 'tt2802144', 207703, 'Kingsman: The Secret Service', 2015, '/17i5YPTfHOjXoieArpATWGRhLj1.jpg', '{80,35,28,12}', 'The story of a super-secret spy organization that recruits an unrefined but promising street kid into the agency''s ultra-competitive training program just as a global threat emerges from a twisted tech genius.', '[{"name":"Taron Egerton","character":"Gary ''Eggsy'' Unwin"},{"name":"Colin Firth","character":"Harry Hart / Galahad"},{"name":"Samuel L. Jackson","character":"Valentine"},{"name":"Mark Strong","character":"Merlin"},{"name":"Sophie Cookson","character":"Roxy"}]', 'Matthew Vaughn', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (636, 'tt3631112', 346685, 'The Girl on the Train', 2016, '/AhTO2QWG0tug7yDoh0XoaMhPt3J.jpg', '{80,9648,53}', 'Rachel Watson, devastated by her recent divorce, spends her daily commute fantasizing about the seemingly perfect couple who live in a house that her train passes every day, until one morning she sees something shocking happen there and becomes entangled in the mystery that unfolds.', '[{"name":"Emily Blunt","character":"Rachel Watson"},{"name":"Rebecca Ferguson","character":"Anna Watson"},{"name":"Haley Bennett","character":"Megan Hipwell"},{"name":"Luke Evans","character":"Scott Hipwell"},{"name":"Justin Theroux","character":"Tom Watson"}]', 'Tate Taylor', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (637, 'tt1250777', 23483, 'Kick-Ass', 2010, '/iHMbrTHJwocsNvo5murCBw0CwTo.jpg', '{28,80}', 'Dave Lizewski is an unnoticed high school student and comic book fan who one day decides to become a super-hero, even though he has no powers, training or meaningful reason to do so.', '[{"name":"Aaron Taylor-Johnson","character":"Dave Lizewski / Kick-Ass"},{"name":"Chloë Grace Moretz","character":"Mindy Macready / Hit Girl"},{"name":"Nicolas Cage","character":"Damon Macready / Big Daddy"},{"name":"Lyndsy Fonseca","character":"Katie Deauxma"},{"name":"Mark Strong","character":"Frank D''Amico"}]', 'Matthew Vaughn', NULL, '2026-07-27 12:00:00.000000') ON CONFLICT ("imdbId") DO NOTHING;
