-- Quiz movie pool: remove all pre-1980 movies and add 103 equally recognizable,
-- popular 1980+ titles that aren't already in the pool.
--
-- Idempotent / safe to run more than once (e.g. against Supabase's SQL Editor):
--   - DELETE is driven by "releaseYear" < 1980, not a fixed id list, so it
--     catches whatever pre-1980 rows actually exist in the target DB.
--   - Every INSERT has ON CONFLICT ("imdbId") DO NOTHING, so re-running after
--     a partial/previous run won't error or duplicate rows.
--
-- Run against the live DB via the Supabase SQL Editor, or:
--   docker cp quiz_movie_pool_1980_migration.sql movie_postgres:/tmp/
--   docker exec -i movie_postgres psql -U <DB_USER> -d <DB_NAME> \
--     -v ON_ERROR_STOP=1 -f /tmp/quiz_movie_pool_1980_migration.sql
--
-- Any pre-1980 row still referenced by daily_movie_quiz history is skipped
-- (FK RESTRICT would otherwise abort the whole migration) instead of failing
-- outright - so a movie already shown as a past day's answer stays in the
-- pool rather than breaking that day's quiz record. That row will just never
-- be picked again once its usedAt is set (it only resurfaces if the whole
-- pool exhausts and resets, which is rare and harmless).
BEGIN;

-- Skip any pre-1980 row still referenced by daily_movie_quiz history (FK RESTRICT
-- would otherwise abort the whole migration); these few will just age out
-- naturally and won't be picked again once the pool cycles past them.
DELETE FROM public.quiz_movie_pool
WHERE "releaseYear" < 1980
  AND id NOT IN (SELECT "poolId" FROM public.daily_movie_quiz);


SELECT pg_catalog.setval('public.quiz_movie_pool_id_seq', (SELECT MAX(id) FROM public.quiz_movie_pool), true);

COMMIT;

-- Verification: run after COMMIT to confirm the result.
-- remaining_pre_1980 should be 0, or a small number that all have
-- used_in_quiz_history = true (these are the FK-RESTRICT-protected rows
-- that intentionally stay behind).
SELECT
  (SELECT count(*) FROM public.quiz_movie_pool) AS total_pool,
  (SELECT count(*) FROM public.quiz_movie_pool WHERE "releaseYear" < 1980) AS remaining_pre_1980;

SELECT p.id, p.title, p."releaseYear"
FROM public.quiz_movie_pool p
WHERE p."releaseYear" < 1980
ORDER BY p."releaseYear";
